mapper.select:


    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
     and a.rule_putaway_id = #{rulePutawayId}
     and a.location_id = #{locationId}
     and a.status = #{status}


${params.dataScope}

select a.rule_putaway_id , group_concat(b.name) as remark from t_rule_putaway_detail a left join t_location b on a.location_id = b.id where a.del_flag = '0' and a.rule_putaway_id in
#{putawayId}
group by a.rule_putaway_id
